dashboard.definition:
{
    "title": "Overview",
    "description": "SOC view of expected data (spec §8.1). Refreshes every 60 s. Filters apply to the KPIs and Needs attention; Recently recovered and Tamper findings are fleet-wide. Click a row to open Host detail.",
    "inputs": {
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_site",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_site"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_owner": {
            "type": "input.dropdown",
            "title": "Owner",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_owner",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_owner"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_index": {
            "type": "input.dropdown",
            "title": "Index",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_index",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_index"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_crit": {
            "type": "input.dropdown",
            "title": "Criticality",
            "options": {
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "1 (highest)",
                        "value": "1"
                    },
                    {
                        "label": "2",
                        "value": "2"
                    },
                    {
                        "label": "3",
                        "value": "3"
                    },
                    {
                        "label": "4",
                        "value": "4"
                    }
                ],
                "token": "f_crit",
                "defaultValue": "*"
            }
        },
        "input_status": {
            "type": "input.dropdown",
            "title": "Status",
            "options": {
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "Host DOWN",
                        "value": "DOWN"
                    },
                    {
                        "label": "Host DEGRADED",
                        "value": "DEGRADED"
                    },
                    {
                        "label": "MISSING",
                        "value": "MISSING"
                    },
                    {
                        "label": "NEVER_SEEN",
                        "value": "NEVER_SEEN"
                    },
                    {
                        "label": "LATE",
                        "value": "LATE"
                    },
                    {
                        "label": "OK",
                        "value": "OK"
                    },
                    {
                        "label": "MUTED",
                        "value": "MUTED"
                    },
                    {
                        "label": "PENDING",
                        "value": "PENDING"
                    },
                    {
                        "label": "INFO",
                        "value": "INFO"
                    }
                ],
                "token": "f_status",
                "defaultValue": "*"
            }
        },
        "input_text": {
            "type": "input.text",
            "title": "Text (entity, description, cause; * wildcard)",
            "options": {
                "token": "f_text",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-24h@h",
                        "latest": "now"
                    },
                    "refresh": "60s",
                    "refreshType": "delay"
                }
            }
        }
    },
    "dataSources": {
        "ds_all": {
            "type": "ds.search",
            "name": "Current dh_status rows",
            "options": {
                "query": "| `dh_ui_status(dh_status)`"
            }
        },
        "ds_kpi": {
            "type": "ds.chain",
            "name": "KPIs (filtered)",
            "options": {
                "extend": "ds_all",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | `dh_ui_kpi`"
            }
        },
        "ds_attention": {
            "type": "ds.chain",
            "name": "Needs attention (filtered)",
            "options": {
                "extend": "ds_all",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | `dh_ui_attention(now())`"
            }
        },
        "ds_opt_site": {
            "type": "ds.chain",
            "name": "Site choices",
            "options": {
                "extend": "ds_all",
                "query": "| where isnotnull(site) AND site!=\"\" | stats count by site | eval label=site, value=site | table label value"
            }
        },
        "ds_opt_owner": {
            "type": "ds.chain",
            "name": "Owner choices",
            "options": {
                "extend": "ds_all",
                "query": "| where isnotnull(owner) AND owner!=\"\" | stats count by owner | eval label=owner, value=owner | table label value"
            }
        },
        "ds_opt_index": {
            "type": "ds.chain",
            "name": "Index choices",
            "options": {
                "extend": "ds_all",
                "query": "| where isnotnull(index) AND index!=\"*\" | stats count by index | eval label=index, value=index | table label value"
            }
        },
        "ds_banner": {
            "type": "ds.search",
            "name": "Banner",
            "options": {
                "query": "| `dh_ui_banner(dh_meta, dh_status, now())`"
            }
        },
        "ds_tamper": {
            "type": "ds.search",
            "name": "Tamper findings in 24 h (first seen)",
            "options": {
                "query": "search index=data_health source=\"dh:tamper\" sourcetype=stash earliest=-31d latest=+1d | eval it=_indextime | `dh_ui_tamper_24h(now())`"
            }
        },
        "ds_tamper_n": {
            "type": "ds.chain",
            "name": "Tamper count",
            "options": {
                "extend": "ds_tamper",
                "query": "| stats count"
            }
        },
        "ds_recovered": {
            "type": "ds.search",
            "name": "Recently recovered (24 h)",
            "options": {
                "query": "search index=data_health source=\"dh:transition\" sourcetype=stash earliest=-7d latest=+1d | `dh_ui_recovered(dh_status, now())`"
            }
        }
    },
    "visualizations": {
        "viz_banner": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_banner"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"banner\") | lastPoint()",
                "backgroundColor": "> primary | seriesByName(\"sev\") | lastPoint() | rangeValue(bannerColors)",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "context": {
                "bannerColors": [
                    {
                        "to": 1,
                        "value": "#1C4F2B"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#7A5D00"
                    },
                    {
                        "from": 3,
                        "value": "#9E1C1C"
                    }
                ]
            }
        },
        "viz_k_hosts": {
            "type": "splunk.singlevalue",
            "title": "Hosts expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"hosts\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_sourcetypes": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetypes\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_sources": {
            "type": "splunk.singlevalue",
            "title": "Sources expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sources\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_ok": {
            "type": "splunk.singlevalue",
            "title": "OK",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"ok\") | lastPoint()",
                "majorColor": "#53A051",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_late": {
            "type": "splunk.singlevalue",
            "title": "Late",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"late\") | lastPoint()",
                "majorColor": "#F8BE34",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_missing": {
            "type": "splunk.singlevalue",
            "title": "Missing (incl. never seen)",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"missing\") | lastPoint()",
                "majorColor": "#DC4E41",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_muted": {
            "type": "splunk.singlevalue",
            "title": "Muted",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"muted\") | lastPoint()",
                "majorColor": "#9B9B9B",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_k_tamper": {
            "type": "splunk.singlevalue",
            "title": "Tamper findings (24 h)",
            "dataSources": {
                "primary": "ds_tamper_n"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
                "majorColor": "#DC4E41",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_attention": {
            "type": "splunk.table",
            "title": "Needs attention",
            "description": "One row per host: DOWN before DEGRADED, then the worst status, criticality (1 first) and duration (oldest first). Click a row for Host detail.",
            "dataSources": {
                "primary": "ds_attention"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_recovered": {
            "type": "splunk.table",
            "title": "Recently recovered (24 h)",
            "dataSources": {
                "primary": "ds_recovered"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_tamper": {
            "type": "splunk.table",
            "title": "Tamper findings (first seen in 24 h, outside Ansible marker windows)",
            "dataSources": {
                "primary": "ds_tamper"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ]
        }
    },
    "layout": {
        "type": "grid",
        "options": {
            "width": 1440,
            "height": 1100
        },
        "globalInputs": [
            "input_site",
            "input_owner",
            "input_index",
            "input_crit",
            "input_status",
            "input_text"
        ],
        "structure": [
            {
                "item": "viz_banner",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 0,
                    "w": 1440,
                    "h": 70
                }
            },
            {
                "item": "viz_k_hosts",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_sourcetypes",
                "type": "block",
                "position": {
                    "x": 180,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_sources",
                "type": "block",
                "position": {
                    "x": 360,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_ok",
                "type": "block",
                "position": {
                    "x": 540,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_late",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_missing",
                "type": "block",
                "position": {
                    "x": 900,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_muted",
                "type": "block",
                "position": {
                    "x": 1080,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_k_tamper",
                "type": "block",
                "position": {
                    "x": 1260,
                    "y": 70,
                    "w": 180,
                    "h": 110
                }
            },
            {
                "item": "viz_attention",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 180,
                    "w": 1440,
                    "h": 480
                }
            },
            {
                "item": "viz_recovered",
                "type": "block",
                "position": {
                    "x": 0,
                    "y": 660,
                    "w": 720,
                    "h": 440
                }
            },
            {
                "item": "viz_tamper",
                "type": "block",
                "position": {
                    "x": 720,
                    "y": 660,
                    "w": 720,
                    "h": 440
                }
            }
        ]
    }
}
